package cli

import (
	"encoding/json"
	"fmt"

	"github.com/spf13/cobra"
)

const flightSearchPreferencesQuery = `query flightSearchPreferences($ruleClassId: ID) {
  travel {
    air {
      searchPreferences(ruleClassId: $ruleClassId) {
        hideMultiCityOption
        isShoppingAcrossPassengerTypesEnabled
        isWorkLocationEnabled
        maxCompanions
        preferredOriginLocation {
          __typename
          id
          name
          address
        }
      }
    }
  }
}`

type flightPreferencesGQLEnvelope struct {
	Data struct {
		Travel struct {
			Air struct {
				SearchPreferences json.RawMessage `json:"searchPreferences"`
			} `json:"air"`
		} `json:"travel"`
	} `json:"data"`
	Errors []gqlErrorEntry `json:"errors"`
}

func newFlightsPreferencesCmd(flags *rootFlags) *cobra.Command {
	var ruleClassID string

	cmd := &cobra.Command{
		Use:         "preferences",
		Short:       "Show your travel policy's flight search defaults",
		Example:     "  concur-pp-cli flights preferences",
		Annotations: map[string]string{"pp:endpoint": "flights.preferences", "pp:method": "POST", "pp:path": "https://www-us2.api.concursolutions.com/cds/graphql", "mcp:read-only": "true"},
		RunE: func(cmd *cobra.Command, args []string) error {
			c, err := flags.newClient()
			if err != nil {
				return err
			}

			variables := map[string]any{}
			if ruleClassID != "" {
				variables["ruleClassId"] = ruleClassID
			}
			body := map[string]any{"query": flightSearchPreferencesQuery, "variables": variables}
			raw, status, err := c.PostQueryWithParams(cmd.Context(), concurGraphQLPath, map[string]string{}, body)
			if err != nil {
				return classifyAPIError(err, flags)
			}
			if status == 401 || status == 403 {
				return fmt.Errorf("not authenticated (HTTP %d): run 'concur-pp-cli auth login --chrome' after logging in to concursolutions.com in Chrome", status)
			}
			if status < 200 || status >= 300 {
				return fmt.Errorf("concur GraphQL BFF returned HTTP %d", status)
			}
			var env flightPreferencesGQLEnvelope
			if err := json.Unmarshal(raw, &env); err != nil {
				return fmt.Errorf("parsing GraphQL response: %w", err)
			}
			if len(env.Errors) > 0 {
				return fmt.Errorf("concur GraphQL error: %s", env.Errors[0].Detail())
			}

			outputData := env.Data.Travel.Air.SearchPreferences
			prov := attachFreshness(DataProvenance{Source: "live"}, flags)

			if wantsHumanTable(cmd.OutOrStdout(), flags) {
				printProvenance(cmd, 1, prov)
			}
			if flags.asJSON || (!isTerminal(cmd.OutOrStdout()) && !flags.csv && !flags.quiet && !flags.plain) {
				filtered := outputData
				if flags.selectFields != "" {
					filtered = filterFields(filtered, flags.selectFields)
				} else if flags.compact {
					filtered = compactFields(filtered)
				}
				wrapped, wrapErr := wrapWithProvenance(filtered, prov)
				if wrapErr != nil {
					return wrapErr
				}
				wrapped, wrapErr = wrapPlatformStructuredOutput(wrapped, flags, "results", true)
				if wrapErr != nil {
					return wrapErr
				}
				return printOutput(cmd.OutOrStdout(), wrapped, true)
			}
			return printOutputWithFlagsMeta(cmd.OutOrStdout(), outputData, flags, map[string]any{"source": "live"})
		},
	}
	cmd.Flags().StringVar(&ruleClassID, "rule-class-id", "", "Look up preferences for a specific travel policy rule class (defaults to your own)")
	return cmd
}
